28	 * The effective date is the one supplied in the request, or the server's current date when
29	 * none was supplied so every stored owner carries the day it was registered. The effective
30	 * date must fall on a business day: a Saturday or Sunday is rolled forward to the following
31	 * Monday. Everything derived from the registration date (such as the membership number's year
32	 * segment) therefore uses this adjusted business-day value.
33	 */
34	@Component
35	public class RegistrationDateAssigner {
36	
37	    private final Clock clock;
38	
39	    private final BusinessDayAdjuster businessDayAdjuster;
40	
41	    public RegistrationDateAssigner(Clock clock, BusinessDayAdjuster businessDayAdjuster) {
42	        this.clock = clock;
43	        this.businessDayAdjuster = businessDayAdjuster;
44	    }
45	
46	    /**
47	     * Sets {@code owner}'s registration date to its effective value, defaulting to the server's
48	     * current date when none was supplied and rolling any weekend date forward to the next
49	     * business day.
50	     *
51	     * @param owner the owner being created
52	     */
53	    public void assign(Owner owner) {
54	        LocalDate effectiveDate = owner.getRegistrationDate() != null
55	            ? owner.getRegistrationDate()
56	            : LocalDate.now(clock);
57	        owner.setRegistrationDate(businessDayAdjuster.toBusinessDay(effectiveDate));
58	    }
59	}
