18	
19	import java.time.Clock;
20	import java.time.LocalDate;
21	
22	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
23	import org.springframework.stereotype.Component;
24	import org.springframework.validation.Errors;
25	import org.springframework.validation.Validator;
26	
27	/**
28	 * Validates the optional {@code registrationDate} supplied on an {@link OwnerFieldsDto} as
29	 * part of the {@code @Valid} pass on the owner request body: a supplied date must not be
30	 * later than the server's current date, so an owner can never be registered in the future.
31	 * <p>
32	 * Registered on the owner controller through {@code @InitBinder} so a future date is recorded
33	 * as a field error on the shared {@link Errors}, surfacing through the usual bad-request
34	 * handling. When no date is supplied the rule does not apply — the effective date is later
35	 * defaulted to the server's current date by {@link RegistrationDateAssigner}.
36	 */
37	@Component
38	public class RegistrationDateValidator implements Validator {
39	
40	    private final Clock clock;
41	
42	    public RegistrationDateValidator(Clock clock) {
43	        this.clock = clock;
44	    }
45	
46	    @Override
47	    public boolean supports(Class<?> clazz) {
48	        return OwnerFieldsDto.class.isAssignableFrom(clazz);
49	    }
50	
51	    @Override
52	    public void validate(Object target, Errors errors) {
53	        LocalDate registrationDate = ((OwnerFieldsDto) target).getRegistrationDate();
54	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now(clock))) {
55	            errors.rejectValue("registrationDate", "registrationDate.future",
56	                "must not be later than the current date");
57	        }
58	    }
59	}
