18	
19	import org.springframework.samples.petclinic.model.Owner;
20	import org.springframework.stereotype.Component;
21	
22	/**
23	 * Assigns, on create, the owner's numeric membership level.
24	 * <p>
25	 * The level starts at {@link #BASE_LEVEL}, gains a point when the owner has an email
26	 * address and another when the owner has no namesakes ({@code namesakeCount} is 0), and
27	 * is capped at {@link #MAX_CREATION_LEVEL}. Level {@code 4} is reserved for tenure and is
28	 * never assigned here. As it reads the owner's namesake count, this must be assigned after
29	 * {@link NamesakeCounter} and before the owner is saved.
30	 */
31	@Component
32	public class MembershipLevelAssigner {
33	
34	    /** The level every owner starts at. */
35	    static final int BASE_LEVEL = 1;
36	
37	    /** The highest level earnable from the owner's own fields on create; level 4 is reserved for tenure. */
38	    static final int MAX_CREATION_LEVEL = 3;
39	
40	    /**
41	     * Assigns {@code owner}'s membership level from its own fields. Call this after the
42	     * namesake count has been assigned and before the owner is saved.
43	     *
44	     * @param owner the owner being created
45	     */
46	    public void assign(Owner owner) {
47	        int level = BASE_LEVEL;
48	        if (hasEmail(owner)) {
49	            level++;
50	        }
51	        if (hasNoNamesakes(owner)) {
52	            level++;
53	        }
54	        owner.setMembershipLevel(Math.min(level, MAX_CREATION_LEVEL));
55	    }
56	
57	    private boolean hasEmail(Owner owner) {
58	        return owner.getEmail() != null && !owner.getEmail().isBlank();
59	    }
60	
61	    private boolean hasNoNamesakes(Owner owner) {
62	        return owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
63	    }
64	}
