24	/**
25	 * Rolls a date forward onto a business day.
26	 * <p>
27	 * Saturdays and Sundays are not business days; either rolls forward to the following Monday.
28	 * A date that already falls on a weekday is returned unchanged.
29	 */
30	@Component
31	public class BusinessDayAdjuster {
32	
33	    /**
34	     * Returns {@code date} if it falls on a weekday, otherwise the next Monday.
35	     *
36	     * @param date the date to adjust
37	     * @return the same date when it is a business day, else the following Monday
38	     */
39	    public LocalDate toBusinessDay(LocalDate date) {
40	        DayOfWeek dayOfWeek = date.getDayOfWeek();
41	        if (dayOfWeek == DayOfWeek.SATURDAY) {
42	            return date.plusDays(2);
43	        }
44	        if (dayOfWeek == DayOfWeek.SUNDAY) {
45	            return date.plusDays(1);
46	        }
47	        return date;
48	    }
49	}
